import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { existsSync, rmSync } from 'node:fs';
const root = new URL('../', import.meta.url);
const run = (...args) => spawnSync(process.execPath, ['cli.js', ...args], { cwd: root, encoding: 'utf8' });
test('--help prints usage and exits 0', () => {
  const r = run('--help');
  assert.equal(r.status, 0);
  for (const c of ['add', 'list', 'done']) assert.ok(r.stdout.includes(c), 'usage mentions ' + c);
});
test('no args prints usage', () => {
  const r = run();
  for (const c of ['add', 'list', 'done']) assert.ok((r.stdout + r.stderr).includes(c), 'usage mentions ' + c);
  assert.ok(!(r.stderr + r.stdout).includes('TypeError'), 'no stack trace');
});
test('unknown command fails cleanly', () => {
  const r = run('lsit');
  assert.ok(r.status === 1 || r.status === 2, 'exit 1 or 2, got ' + r.status);
  assert.ok(r.stderr.includes('--help'), 'stderr points at --help');
  assert.ok(!(r.stderr + r.stdout).includes('TypeError'), 'no stack trace');
});
test('commands still work', () => {
  const file = new URL('../todos.json', import.meta.url);
  if (existsSync(file)) rmSync(file);
  assert.equal(run('add', 'buy', 'milk').stdout.trim(), 'Added #1');
  assert.equal(run('add', 'walk').stdout.trim(), 'Added #2');
  assert.equal(run('done', '1').stdout.trim(), 'Done #1');
  assert.equal(run('list').stdout, '1. [x] buy milk\n2. [ ] walk\n');
  rmSync(file);
});

