import { existsSync, readFileSync, writeFileSync } from 'node:fs';

const FILE = new URL('./todos.json', import.meta.url);
const load = () => (existsSync(FILE) ? JSON.parse(readFileSync(FILE, 'utf8')) : []);
const save = (todos) => writeFileSync(FILE, JSON.stringify(todos, null, 2) + '\n');

const commands = {
  add(words) {
    const todos = load();
    todos.push({ text: words.join(' '), done: false });
    save(todos);
    console.log('Added #' + todos.length);
  },
  list() {
    for (const [i, t] of load().entries()) console.log((i + 1) + '. ' + (t.done ? '[x] ' : '[ ] ') + t.text);
  },
  done([n]) {
    const todos = load();
    todos[Number(n) - 1].done = true;
    save(todos);
    console.log('Done #' + n);
  },
};

const USAGE = ['Usage: node cli.js <command>', '', '  add <text>   add a todo', '  list         show all todos', '  done <n>     mark todo n as done', '  --help       show this help'].join('\n');

const [cmd, ...rest] = process.argv.slice(2);
if (!cmd || cmd === '--help' || cmd === '-h') {
  console.log(USAGE);
  process.exit(0);
}
if (!Object.hasOwn(commands, cmd)) {
  console.error('Unknown command: ' + cmd + '. Run with --help to see the commands.');
  process.exit(1);
}
commands[cmd](rest);
